// On the order confirmation page, before the GTM container snippet or right after the order is known
window.dataLayer = window.dataLayer || [];
dataLayer.push({ ecommerce: null });  // clear the previous ecommerce object
dataLayer.push({
  event: "purchase",
  ecommerce: {
    transaction_id: "T-10482",
    value: 119.00,
    currency: "EUR",
    items: [{ item_id: "ARCH3-42", item_name: "StrideLab Arch 3", price: 119.00, quantity: 1 }]
  }
});

